import {parseDocument,countChars,compileSources,compareParagraph,buildReport,LIMITS} from '../precheck/engine.mjs';
import {repository} from '../precheck/store.mjs';
import {selectedDetectionSections,detectionChars,selectDetectionReports,validateDetectionSource} from './detection-model.mjs';
import {keys,list,projects,recordTask} from './state.mjs';
import {esc,icon,formatDate,download} from './ui.mjs';
import {reportHtml} from '../precheck/export.mjs';
const $=s=>document.querySelector(s);
let metaDraft={title:'',projectId:'',degree:'本科'};
let ctx,controller,view=0,input=null,parsed=null,ids=[],sources=[],reports=[],tab='check',busy=false,run=null,storageError='',filters={query:'',project:'all'},lastResult=null;
export function detectionRouteGuard(){if(!busy||!$('#detection-space'))return true;ctx.notify('正在本地处理，请等待完成或取消比对后再离开。');return false;}
window.addEventListener('beforeunload',e=>{if(busy&&$('#detection-space')){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a&&a.target!=='_blank'&&busy&&$('#detection-space')){e.preventDefault();e.stopImmediatePropagation();ctx.notify('请等待完成或取消比对后再离开。');}},true);
export async function mountDetection(options){ctx=options;controller?.abort();controller=new AbortController();const token=++view;$('.dashboard').innerHTML='<p id="detection-loading" class="hub-footnote">正在读取本地检测记录…</p>';try{[sources,reports]=await Promise.all([repository.all('sources'),repository.all('reports')]);storageError='';}catch{sources=[];reports=[];storageError='无法读取本地材料或报告，请检查浏览器存储权限。';}if(token!==view||!$('#detection-loading'))return;draw();$('.dashboard').addEventListener('click',handle,{signal:controller.signal});}
function draw(){const rows=selectDetectionReports(reports,filters);$('.dashboard').innerHTML=`<div id="detection-space"><div class="hub-heading"><div><h1>论文检测</h1><p>上传论文，核对相似来源，查看可追溯的检测报告。</p></div><div class="hub-heading-actions"><a class="btn secondary" href="/precheck/#/history">${icon('clock',17)}查看检测记录</a></div></div><div class="det-layout"><section class="card det-create"><h2>创建检测任务</h2><nav class="det-tabs" aria-label="检测类型"><button data-det-tab="check" aria-pressed="${tab==='check'}" class="${tab==='check'?'active':''}">论文查重 <small>本地比对可用</small></button><button data-det-tab="ai" aria-pressed="${tab==='ai'}" class="${tab==='ai'?'active':''}">AI 率检测 <small>待上线</small></button></nav>${storageError?`<p class="error-text" role="alert">${esc(storageError)}</p>`:''}${tab==='ai'?`<div class="det-ai-empty">${icon('shield',38)}<h3>AI 率检测尚未接入</h3><p>当前不接受检测提交，不生成 AI 百分比，也不承诺通过其他平台检测。</p><button class="btn primary" disabled>检测服务待上线</button><button class="btn secondary" data-det-tab="check">返回论文查重</button></div>`:`<ol class="rev-steps det-steps">${['上传论文','核对正文','确认范围','查看报告'].map((s,i)=>`<li class="${i===(parsed?2:input?1:0)?'active':''}"><span>${i+1}</span>${s}</li>`).join('')}</ol><div class="det-meta"><div><label for="det-title">论文标题</label><input id="det-title" maxlength="200" value="${esc(input?.title||metaDraft.title||'')}" placeholder="例如：课堂反馈研究"></div><div><label for="det-project">所属项目</label><select id="det-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===(input?.projectId??metaDraft.projectId)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div><label for="det-degree">学段 / 身份</label><select id="det-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===(input?.degree||metaDraft.degree||'本科')?'selected':''}>${d}</option>`).join('')}</select></div></div><label class="det-upload" for="det-file">${icon(input?'file':'upload',36)}<b>${input?esc(input.name):'拖拽论文到这里，或点击上传'}</b><span>DOCX / PDF / TXT · 最大 50MB · PDF 最多 150 页</span><small>${input?'重新选择会替换当前输入，不影响已保存报告。':'文本型 PDF；扫描文件不支持 OCR。'}</small><input id="det-file" type="file" accept=".docx,.pdf,.txt"></label><div class="det-input-actions"><button class="btn secondary" data-det-action="existing">${icon('folder',16)}选择已有成果</button><button class="btn secondary" data-det-action="paste">粘贴 / 核对正文</button></div><p id="det-status" class="hub-footnote" role="status">${input?`已提取 ${countChars(input.text).toLocaleString('zh-CN')} 个有效字符；请核对正文。`:''}</p>${input?.warnings?.length?`<details class="det-warning"><summary>解析提示 ${input.warnings.length} 条</summary>${input.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</details>`:''}<div class="det-scope"><div><b>当前检测范围：本地对照材料</b><p>仅与实际提供的对照正文比对，尚未接入全网检索。</p><small>已添加 ${sources.length} 份材料 · 不自动使用演示语料</small></div><button class="btn secondary" data-det-action="sources">管理对照材料</button></div>${parsed?`<section class="det-confirm"><h3>确认检测章节</h3><p>目录、参考文献、致谢、附录固定排除，其他章节可自行选择。</p><div class="det-sections">${parsed.sections.map(s=>`<label><input type="checkbox" data-det-section="${esc(s.id)}" ${s.excluded?'disabled':ids.includes(s.id)?'checked':''}><span><b>${esc(s.title)}</b><small>${s.paragraphs.reduce((n,p)=>n+countChars(p.text),0)} 字${s.excluded?' · 固定排除':''}</small></span></label>`).join('')}</div><p>有效检测字数：<b id="det-count">${detectionChars(parsed,ids)}</b>（字母与数字，不含标点和空白）</p><details><summary>查看已解析的正文与章节</summary><div class="det-text-preview">${parsed.sections.map(s=>`<h4>${esc(s.title)}</h4>${s.paragraphs.map(p=>`<p>${esc(p.text)}</p>`).join('')}`).join('')}</div></details></section>`:`<div class="det-settings">${icon('settings',18)}<div><b>检测范围说明</b><p>解析后逐章确认；目录、参考文献、致谢和附录不参与计分。</p></div></div>`}<div id="det-progress" class="det-progress" role="status" hidden></div><div class="det-submit"><p>本地结果不等同于知网、万方、维普。</p><button class="btn primary" id="det-next" data-det-action="${parsed?'run':'confirm'}">${parsed?'开始本地比对':'上传并核对正文'}${icon('arrow',17)}</button></div>${!sources.length?'<p class="hub-footnote">请先添加有权使用的对照正文；没有材料时不会启动检测或生成重复率。</p>':''}`}</section><aside class="det-side"><section class="card"><h2>${icon('chart',19)}检测范围与能力</h2><div class="det-capabilities">${[['本地文本比对','可用','ready'],['全网学术检索','待接入',''],['语义相似度','待接入',''],['AI 率检测','待上线','']].map(([n,s,c])=>`<div><b>${n}</b><span class="${c}">${s}</span></div>`).join('')}</div></section><section class="card"><h2>${icon('file',19)}报告包含什么</h2>${[['chart','章节相似度','定位实际匹配所在的章节'],['search','逐段标记与来源对照','查看匹配文本和来源证据'],['book','来源与引用状态','保留提供的 URL、DOI、作者与年份'],['file','报告导出','HTML / JSON，打印保存 PDF']].map(([i,t,d])=>`<div class="det-report-feature">${icon(i,21)}<div><b>${t}</b><p>${d}</p></div></div>`).join('')}<a class="det-link" href="/precheck/">体验示例流程 →</a><p class="hub-footnote">引用识别仅支持有限规则，需人工核对；无语义分数。</p></section><section class="card"><h2>${icon('shield',19)}数据与隐私</h2><p>本地解析，不自动上传</p><p>当前浏览器保存，请及时导出</p><p>无来源证据，不判定外部重复</p><small>DOI 与 URL 由用户填写，尚未联网核验。0% 只说明当前材料中未发现符合规则的匹配。</small></section></aside></div><section class="card det-history"><header><h2>${icon('clock',19)}最近检测报告 <small>${reports.length} 份本地记录</small></h2><a href="/precheck/#/history">全部记录 →</a></header><div class="det-history-toolbar"><input id="det-query" aria-label="搜索检测报告" placeholder="搜索论文名称" value="${esc(filters.query)}"><select id="det-history-project" aria-label="检测报告项目"><option value="all">所有项目</option><option value="none" ${filters.project==='none'?'selected':''}>未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${filters.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div id="det-history-rows">${historyRows(rows)}</div></section><div class="hub-backup-strip det-backup">${icon('shield',23)}<div><b>从检测到修改，让问题有据可查</b><p>修改后需重新检测，不推测新结果；本地记录不代表正式学术数据库检测。</p></div><a class="btn secondary" href="#category/revision">前往修改与润色 →</a></div></div>`;
$('#det-file')?.addEventListener('change',e=>{if(e.target.files[0])readFile(e.target.files[0]);});$('.det-upload')?.addEventListener('dragover',e=>{e.preventDefault();});$('.det-upload')?.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files[0])readFile(e.dataTransfer.files[0]);});document.querySelectorAll('[data-det-section]').forEach(el=>el.onchange=()=>{ids=el.checked?[...new Set([...ids,el.dataset.detSection])]:ids.filter(id=>id!==el.dataset.detSection);$('#det-count').textContent=detectionChars(parsed,ids);});$('#det-query').oninput=e=>{filters.query=e.target.value;updateHistory();};$('#det-history-project').onchange=e=>{filters.project=e.target.value;updateHistory();};}
function historyRows(rows){return rows.length?`<div class="det-table-scroll"><table class="det-table"><thead><tr><th>文稿名称</th><th>类型与范围</th><th>检测时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.slice(0,8).map(r=>`<tr><td><a href="/precheck/#/report/${encodeURIComponent(r.id)}">${esc(r.title)}</a><small>${esc(projects().find(p=>p.id===r.projectId)?.name||'未归入项目')}</small></td><td><span>${r.mode==='demo'||r.sources?.some(s=>s.kind==='demo')?'含演示材料':'本地文本比对'}</span></td><td>${esc(formatDate(r.createdAt))}</td><td><span class="det-complete">已完成</span></td><td><a href="/precheck/#/report/${encodeURIComponent(r.id)}">查看报告</a><button data-det-export="${esc(r.id)}">导出</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="det-history-empty"><b>${reports.length?'没有匹配的报告':'暂无检测报告'}</b><p>${reports.length?'调整搜索关键词或项目筛选。':'完成实际本地比对后，报告会显示在这里；不填充模拟记录。'}</p></div>`;}
function updateHistory(){$('#det-history-rows').innerHTML=historyRows(selectDetectionReports(reports,filters));}
function metadata(){return {title:$('#det-title')?.value.trim()||input?.title||metaDraft.title||'未命名论文',projectId:$('#det-project')?$('#det-project').value:input?.projectId||metaDraft.projectId||'',degree:$('#det-degree')?.value||input?.degree||metaDraft.degree||'本科'};}
async function readFile(file){if(busy)return;const root=$('#detection-space'),meta=metadata();if(file.size>LIMITS.fileBytes){ctx.notify('文件超过 50MB。');return;}if(!/\.(docx|pdf|txt)$/i.test(file.name)){ctx.notify('请选择 DOCX、PDF 或 UTF-8 TXT。');return;}if(input&&!window.confirm('重新导入会替换当前尚未检测的正文，已保存报告不受影响。继续吗？'))return;busy=true;$('#det-next').disabled=true;$('#det-status').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js');const result=await extractFile(file);if($('#detection-space')!==root)return;validateText(result.text);input={...meta,title:$('#det-title').value.trim()||file.name.replace(/\.[^.]+$/,'').slice(0,200),name:file.name,text:result.text,warnings:result.warnings||[],pages:result.pages};parsed=null;ids=[];}catch(e){ctx.notify(e.message||'文件解析失败');}finally{busy=false;if($('#detection-space')===root)draw();}}
function validateText(text){if(text.length>200000||countChars(text)>LIMITS.textChars)throw Error('本地最多 80,000 个有效字符，原文最多 200,000 字符。');if(countChars(text)<20)throw Error('请提供至少 20 个有效字符；扫描 PDF 请先 OCR。');}
function pasteForm(source){const meta=metadata();ctx.modal('粘贴或核对论文正文',`<form class="hub-form" id="det-paste-form"><label for="det-paste">论文正文</label><textarea id="det-paste" required rows="12" maxlength="200000">${esc(source?.text??input?.text??'')}</textarea><p class="hub-footnote">确认正文后重新解析章节；不自动上传。最多 80,000 个有效字符。</p><p id="det-paste-error" role="alert"></p><button class="btn primary">确认正文</button></form>`);$('#det-paste-form').onsubmit=e=>{e.preventDefault();try{const text=$('#det-paste').value;validateText(text);input={...meta,...source,title:source?.title||meta.title,text,name:source?'已有成果正文.txt':input?.name||'粘贴正文.txt',warnings:source?[]:input?.warnings||[]};parsed=null;ids=[];$('#workspace-dialog').close();draw();}catch(err){$('#det-paste-error').textContent=err.message;}};}
function existing(){const rows=list(keys.drafts).filter(d=>d.text?.trim());ctx.modal('选择已有成果',`<p class="hub-intro">复制保存的文本，不覆盖原成果；请核对结构模板是否已填写正文。</p><div class="rev-existing">${rows.map((r,i)=>`<button data-det-existing="${i}"><b>${esc(r.title)}</b><small>${esc(formatDate(r.updatedAt))}</small></button>`).join('')||'<p>没有已保存的文本成果，请上传或粘贴正文。</p>'}</div>`);document.querySelectorAll('[data-det-existing]').forEach(b=>b.onclick=()=>pasteForm(rows[Number(b.dataset.detExisting)]));}
function sourceDialog(){ctx.modal('管理本地对照材料',`<p class="hub-intro">只使用你有权提供的实际正文，不抓取或下载付费全文。演示材料不自动参与本页检测。</p>${sources.map(s=>`<div class="det-source-row"><b>${esc(s.title)}</b><small>${countChars(s.text||'')} 个有效字符 · ${esc(s.provider)}</small></div>`).join('')||'<p>尚无对照材料，无法启动比对。</p>'}<button class="btn primary" id="det-add-source">添加对照正文</button><p class="hub-footnote">最多 10 份用户材料；每份 20,000 个有效字符。来源信息尚未联网核验。</p>`);$('#det-add-source').onclick=()=>{if(sources.length>=10){ctx.notify('最多 10 份对照材料。');return;}sourceForm();};}
function sourceForm(){ctx.modal('添加实际对照材料',`<form class="hub-form" id="det-source-form"><label for="ds-title">来源标题 *</label><input id="ds-title" maxlength="200" required><div class="hub-form-row"><div><label for="ds-authors">作者（可选）</label><input id="ds-authors" maxlength="1000"></div><div><label for="ds-year">年份（可选）</label><input id="ds-year" maxlength="4"></div></div><label for="ds-doi">DOI（可选）</label><input id="ds-doi" maxlength="300"><label for="ds-url">来源 URL（可选）</label><input id="ds-url" maxlength="2000" placeholder="https://…"><label for="ds-text">实际对照正文 *</label><textarea id="ds-text" required rows="8" maxlength="100000"></textarea><label class="rev-resolved"><input id="ds-permission" type="checkbox" required>我有权使用这份材料进行本地文本比对</label><p id="ds-error" role="alert"></p><button class="btn primary" id="ds-save">保存材料</button></form>`);$('#det-source-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;try{const values=validateDetectionSource({title:$('#ds-title').value,authors:$('#ds-authors').value,year:$('#ds-year').value,doi:$('#ds-doi').value,url:$('#ds-url').value,text:$('#ds-text').value});$('#ds-save').disabled=true;const latest=await repository.all('sources');if(latest.length>=10)throw Error('最多保存 10 份用户材料。');await repository.save('sources',{...values,id:crypto.randomUUID(),createdAt:new Date().toISOString()});sources=await repository.all('sources');if($('#det-source-form')===form){$('#workspace-dialog').close();retainMeta();draw();ctx.notify('对照正文已保存，可用于实际比对。');}}catch(err){if($('#det-source-form')===form){$('#ds-error').textContent=err.message||'本地保存失败';$('#ds-save').disabled=false;}}};}
function retainMeta(){metaDraft=metadata();if(input)input={...input,...metaDraft};}
async function runComparison(){if(!parsed)return;if(!detectionChars(parsed,ids)){ctx.notify('请至少选择一个包含正文的章节。');return;}retainMeta();busy=true;lastResult=null;run=new AbortController();const signal=run.signal,root=$('#detection-space');$('#det-next').disabled=true;$('#det-progress').hidden=false;$('#det-progress').innerHTML='<p id="det-run-detail">读取实际对照材料…</p><progress id="det-run-progress" max="100" value="0"></progress><button class="btn secondary" id="det-cancel">取消本地比对</button>';$('#det-cancel').onclick=()=>run?.abort();try{sources=await repository.all('sources');if(!sources.length)throw Error('没有实际对照正文，请先添加材料。');if(signal.aborted)throw new DOMException('Cancelled','AbortError');const compiled=compileSources(sources);if(!compiled.length)throw Error('没有可用的实际对照正文。');const paragraphs=selectedDetectionSections(parsed,ids).flatMap(s=>s.paragraphs),matches=[];for(let n=0;n<paragraphs.length;n++){if(signal.aborted)throw new DOMException('Cancelled','AbortError');matches.push(...compareParagraph(paragraphs[n],compiled,parsed.text));$('#det-run-detail').textContent=`已实际比对 ${n+1} / ${paragraphs.length} 段`;$('#det-run-progress').value=Math.round(100*(n+1)/paragraphs.length);await new Promise(r=>setTimeout(r,0));}if(signal.aborted)throw new DOMException('Cancelled','AbortError');const report={...buildReport({...parsed,title:input.title},sources,matches,{sectionIds:ids,fileName:input.name,degree:input.degree,mode:'local'}),projectId:input.projectId||'',scope:'user-local-sources',inputSourceId:input.id||null};$('#det-cancel').disabled=true;$('#det-run-detail').textContent='比对完成，正在保存报告…';lastResult=report;await repository.save('reports',report);reports=await repository.all('reports');try{recordTask({id:'report-'+report.id,title:report.title,kind:'本地文本比对',projectId:report.projectId,status:'completed',url:'/precheck/#/report/'+report.id});}catch{ctx.notify('报告已保存，操作记录未能保存。');}lastResult=null;ctx.modal('本地比对完成',`<p>已保存实际报告：${esc(report.title)}</p><p>相似度 ${(report.ratio*100).toFixed(1)}% · ${report.totalChars} 个有效字符 · ${report.sourceCount} 个匹配来源。</p><p class="hub-footnote">仅针对 ${sources.length} 份实际对照正文；不代表全网重复率。</p><a class="btn primary" href="/precheck/#/report/${encodeURIComponent(report.id)}">查看交互报告 →</a>`);}catch(err){if(lastResult){ctx.modal('报告未能保存',`<p>比对已经完成，但浏览器未能保存报告。请导出当前会话报告，离开或刷新后可能丢失。</p><button class="btn primary" id="det-unsaved-export">导出报告 JSON</button>`);$('#det-unsaved-export').onclick=()=>download(lastResult.title+'-未保存报告.json',JSON.stringify(lastResult,null,2),'application/json');}else ctx.notify(err.name==='AbortError'?'已取消本地比对，未生成报告。':err.message||'比对失败，请重试。');}finally{busy=false;run=null;if($('#detection-space')===root)draw();}}
function handle(e){if(busy)return;try{const t=e.target.closest('[data-det-tab]');if(t){retainMeta();tab=t.dataset.detTab;draw();return;}const ex=e.target.closest('[data-det-export]');if(ex){const r=reports.find(r=>r.id===ex.dataset.detExport);if(r){download(r.title+'-PaperKnow报告.html',reportHtml(r),'text/html;charset=utf-8');ctx.notify('已发起报告下载，请确认浏览器保存。');}return;}const b=e.target.closest('[data-det-action]');if(!b)return;switch(b.dataset.detAction){case'existing':retainMeta();existing();break;case'paste':retainMeta();pasteForm();break;case'sources':retainMeta();sourceDialog();break;case'confirm':if(!input){ctx.notify('请先上传论文、粘贴正文或选择已有成果。');return;}retainMeta();parsed=parseDocument(input.text,input.title);ids=parsed.sections.filter(s=>!s.excluded).map(s=>s.id);draw();break;case'run':runComparison();break;}}catch(err){ctx.notify(err.message||'操作失败');}}
